UPDATE sys_ticket
SET resolved_at = LOCALTIMESTAMP, status = 'RESOLVED'
WHERE id = #{id} AND status = 'PROCESSING' AND assignee_id = #{assigneeId}

UPDATE sys_ticket
SET closed_at = LOCALTIMESTAMP, status = 'CLOSED'
WHERE id = #{id} AND status = 'RESOLVED' AND creator_id = #{creatorId}

UPDATE sys_ticket
SET status = 'CANCELED'
WHERE id = #{id} AND status = 'PENDING' AND creator_id = #{creatorId}

UPDATE sys_ticket
SET title = #{ticket.title},description = #{ticket.description},priority = #{ticket.priority},category = #{ticket.category},deadline_at =#{ticket.deadlineAt}
WHERE id = #{ticket.id} AND creator_id = #{creatorId} AND status = 'PENDING'
